<?php

declare(strict_types=1);

namespace App\Policies;

use App\Models\Faq;
use Illuminate\Auth\Access\HandlesAuthorization;
use Illuminate\Foundation\Auth\User as AuthUser;

/**
 * Filament Shield policy for Faq. Generated by `php artisan shield:generate`;
 * each ability maps to a "{Action}:Faq" permission seeded by RoleSeeder.
 * super_admin bypasses these checks (Gate::before in Shield).
 *
 * Regenerating policies with shield:generate may overwrite these docblocks.
 */
class FaqPolicy
{
    use HandlesAuthorization;

    /**
     * Determine whether the admin may list Faq records.
     *
     * @param  AuthUser  $authUser  The signed-in admin.
     * @return bool True when the admin holds the "ViewAny:Faq" permission.
     */
    public function viewAny(AuthUser $authUser): bool
    {
        return $authUser->can('ViewAny:Faq');
    }

    /**
     * Determine whether the admin may view one Faq record.
     *
     * @param  AuthUser  $authUser  The signed-in admin.
     * @param  Faq  $faq  The record being authorized.
     * @return bool True when the admin holds the "View:Faq" permission.
     */
    public function view(AuthUser $authUser, Faq $faq): bool
    {
        return $authUser->can('View:Faq');
    }

    /**
     * Determine whether the admin may create Faq records.
     *
     * @param  AuthUser  $authUser  The signed-in admin.
     * @return bool True when the admin holds the "Create:Faq" permission.
     */
    public function create(AuthUser $authUser): bool
    {
        return $authUser->can('Create:Faq');
    }

    /**
     * Determine whether the admin may edit a Faq record.
     *
     * @param  AuthUser  $authUser  The signed-in admin.
     * @param  Faq  $faq  The record being authorized.
     * @return bool True when the admin holds the "Update:Faq" permission.
     */
    public function update(AuthUser $authUser, Faq $faq): bool
    {
        return $authUser->can('Update:Faq');
    }

    /**
     * Determine whether the admin may delete one Faq record.
     *
     * @param  AuthUser  $authUser  The signed-in admin.
     * @param  Faq  $faq  The record being authorized.
     * @return bool True when the admin holds the "Delete:Faq" permission.
     */
    public function delete(AuthUser $authUser, Faq $faq): bool
    {
        return $authUser->can('Delete:Faq');
    }

    /**
     * Determine whether the admin may bulk delete Faq records.
     *
     * @param  AuthUser  $authUser  The signed-in admin.
     * @return bool True when the admin holds the "DeleteAny:Faq" permission.
     */
    public function deleteAny(AuthUser $authUser): bool
    {
        return $authUser->can('DeleteAny:Faq');
    }

    /**
     * Determine whether the admin may restore one soft-deleted Faq record.
     *
     * @param  AuthUser  $authUser  The signed-in admin.
     * @param  Faq  $faq  The record being authorized.
     * @return bool True when the admin holds the "Restore:Faq" permission.
     */
    public function restore(AuthUser $authUser, Faq $faq): bool
    {
        return $authUser->can('Restore:Faq');
    }

    /**
     * Determine whether the admin may permanently delete one Faq record.
     *
     * @param  AuthUser  $authUser  The signed-in admin.
     * @param  Faq  $faq  The record being authorized.
     * @return bool True when the admin holds the "ForceDelete:Faq" permission.
     */
    public function forceDelete(AuthUser $authUser, Faq $faq): bool
    {
        return $authUser->can('ForceDelete:Faq');
    }

    /**
     * Determine whether the admin may permanently bulk delete Faq records.
     *
     * @param  AuthUser  $authUser  The signed-in admin.
     * @return bool True when the admin holds the "ForceDeleteAny:Faq" permission.
     */
    public function forceDeleteAny(AuthUser $authUser): bool
    {
        return $authUser->can('ForceDeleteAny:Faq');
    }

    /**
     * Determine whether the admin may bulk restore soft-deleted Faq records.
     *
     * @param  AuthUser  $authUser  The signed-in admin.
     * @return bool True when the admin holds the "RestoreAny:Faq" permission.
     */
    public function restoreAny(AuthUser $authUser): bool
    {
        return $authUser->can('RestoreAny:Faq');
    }

    /**
     * Determine whether the admin may duplicate a Faq record.
     *
     * @param  AuthUser  $authUser  The signed-in admin.
     * @param  Faq  $faq  The record being authorized.
     * @return bool True when the admin holds the "Replicate:Faq" permission.
     */
    public function replicate(AuthUser $authUser, Faq $faq): bool
    {
        return $authUser->can('Replicate:Faq');
    }

    /**
     * Determine whether the admin may reorder Faq records.
     *
     * @param  AuthUser  $authUser  The signed-in admin.
     * @return bool True when the admin holds the "Reorder:Faq" permission.
     */
    public function reorder(AuthUser $authUser): bool
    {
        return $authUser->can('Reorder:Faq');
    }
}
